-- 2409 🏋️ Exercises from the book "elite-academy-coaching-the-secrets-behind-the-development-program-for-pep-guardi" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'elite-academy-coaching-the-secrets-behind-the-development-program-for-pep-guardi');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('4-line passing drill, three combinations', 'passing_unopposed', 'unopposed', 'in_possession', 53, 53, 'Session 1: Practice 1', 'Man City Academy (Darren Bowman)', 'Angles of support and playing through the thirds with varied combinations.', 'Four lines of poles across the area, one player at each pole plus an extra at each end; groups of 6 working three lanes (left, middle, right).', 'Left lane: A one-two with B, then C sets back for B to play D. Middle: A to C, C sets for B, B plays D. Right: A to C who sets for B; D spins round his pole, B finds him, he turns and plays a deep run that dribbles back to the start.', 'Central players start on the poles and only move off when the ball breaks the line.', 'Rotate A to B to C to D to A; repeat from the other end.', 'Timing of runs and passes for rhythm; receive on the back foot to play forward or back.', 'Groups of 6', 6, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 10),
  ('3v3+2 directional possession, play inside/out', 'positional_game', 'overload', 'in_possession', 54, 54, 'Session 1: Practice 2', 'Man City Academy (Darren Bowman)', 'Break lines by playing in between and around to move the ball end to end.', '15 x 10 yard area (size by level); end players on each end line plus a central joker, 3v3 inside.', 'Team in possession plus the two end players and joker make a 5v3; they try to move the ball from one end to the other and keep it. If the 3 pressing defenders win it, roles switch.', 'Ball on the floor; ball carrier should always have a short, medium and long option.', NULL, 'Play your position, be ready to attack and defend, play between and behind, quick forward combinations, penetrate.', '3v3 (+2)', 8, 8, '15 x 10 yards', 13.7, 9.1, NULL, false, false, true, NULL, 20),
  ('End to end overload wave game 1v1 to 6v5', 'small_sided_game', 'overload', 'in_possession', 55, 55, 'Session 1: Practice 3', 'Man City Academy (Darren Bowman)', 'Exploit growing attacking overloads at high intensity and tempo.', '60 x 40 yard area, 2 small goals, two teams of 6 waiting at the ends; coach on the side with balls.', 'Coach serves ball 1 for a 1v1; ball 2 brings in one more defender for a 2v1 the other way; each new ball adds players (3v2, 4v3, 5v4, 6v5).', 'Defenders who win the ball can score too; team with most goals wins.', NULL, 'Tempo and decisions change as numbers grow, very fast early to medium at the end.', '2 teams of 6', 12, 12, '60 x 40 yards', 54.9, 36.6, NULL, true, false, true, NULL, 30),
  ('Back to back goals 5v5 create 3v2', 'small_sided_game', 'opposed', 'in_possession', 56, 56, 'Session 1: Practice 4', 'Man City Academy (Darren Bowman)', 'Create 3v2 overloads through quick combinations and occupying the right spaces.', '60 x 40 yard area split in half, 2 large goals with GKs placed back to back in the middle.', 'Coach passes in; team in possession aims to build a 3v2 overload in the opposite half and score. Transitions should be exploited.', NULL, 'Lower levels: 2v2 in both halves plus 2 floating jokers; or 3v3 in one half and 2v2 in the other.', 'Keep possession, then go when the overload is on; timing and situation recognition.', '5v5 (+GKs)', 12, 14, '60 x 40 yards', 54.9, 36.6, NULL, true, true, true, NULL, 40),
  ('One-touch triangle drill with third man run', 'passing_unopposed', 'unopposed', 'in_possession', 58, 58, 'Session 2: Practice 1', 'Man City Academy (Darren Bowman)', 'One-touch passing and third man runs to break a line.', 'Mannequins/poles 15-30 yards apart; pole and cone gates; two wide poles act as defenders to check away from.', 'A passes to B, B takes a first touch through the gate and plays the run of C, C passes to A2 and the sequence repeats.', 'One touch at high ball speed; body side-on facing forward.', 'Rotate A to B to C to A2; change direction to use both feet.', 'Eye contact for timing; weight of pass to break the line.', NULL, NULL, NULL, '15-30 yards between poles', NULL, NULL, NULL, false, false, true, NULL, 50),
  ('6v6 dual direction transition game', 'transition', 'opposed', 'to_attack', 59, 59, 'Session 2: Practice 2', 'Man City Academy (Darren Bowman)', 'All four phases of the game with fast transitions in two directions.', 'Pitch with red end zones on both sides and blue end zones at both ends; 6v6.', 'Blues attack side to side, scoring by receiving or dribbling into a red side zone, then attack the opposite side. Reds defend and on winning the ball counter end to end into a blue zone; blues transition fast to stop them.', '1 point per zone entry; coach may limit time or touches to set tempo.', NULL, 'Decision making and game intelligence in all phases.', '6v6', 12, 12, NULL, NULL, NULL, NULL, false, false, true, NULL, 60),
  ('2-zone 3-team SSG for 3v2 finish', 'phase_of_play', 'overload', 'in_possession', 60, 60, 'Session 2: Practice 3', 'Man City Academy (Darren Bowman)', 'Controlled build-up from the GK into a 3v2 overload to finish.', '30 x 15 yard area in two halves, two goals with GKs, 3 teams of 5 (2 play, 1 waits); only 2 defenders allowed in their low half.', 'GK plays to a full back, who passes into the forward, who sets for a central midfielder, creating a 3v2 in the attacking half; full backs stay back. If reds win it they counter 5v5.', 'Third team rotates in after a goal or after 3-5 minutes.', NULL, 'Controlled diamond possession until the right moment; dynamic counter before support recovers.', '3 teams of 5 + GKs', 17, 17, '30 x 15 yards', 27.4, 13.7, NULL, true, true, true, NULL, 70),
  ('Continuous 2v2 pairs wave game', 'one_v_one', 'opposed', 'in_possession', 61, 61, 'Session 2: Practice 4', 'Man City Academy (Darren Bowman)', 'Fast, intense 2v2 attacking and defending with quick finishing.', 'Area with 2 large goals and GKs; 2 teams of 6 in pairs waiting beside each goal.', 'GK passes to a blue pair who attack a red pair 2v2; if reds win it they score at the other end. When the phase ends the other GK serves to the next red pair, who attack the next blue pair.', 'Continuous, next pairs enter after every phase.', NULL, 'Use overlaps, one-twos, 1v1s and lay-offs; quick reactions and finish choice.', '2 teams of 6 in pairs + GKs', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 80),
  ('Figure of 8 diamond passing, free decisions', 'passing_unopposed', 'unopposed', 'in_possession', 63, 63, 'Session 3: Practice 1', 'Man City Academy (Darren Bowman)', 'Switch play through the DM and make free passing decisions in a diamond pattern.', '40 x 20 yard area, diamond of poles with two groups forming triangles either side; central player C as the DM.', 'Players move the ball around and switch through C, choosing their own combinations; later add blind side runs, overlaps and diagonal passes into the pocket.', NULL, 'Rotate A to B to C to D to A.', 'Half-turn body shape; break line with first touch; switch then play between and behind; eye contact.', '2 groups', NULL, NULL, '40 x 20 yards', 36.6, 18.3, NULL, false, false, true, NULL, 90),
  ('7v7+1 end goal zone diamond possession', 'positional_game', 'overload', 'in_possession', 64, 64, 'Session 3: Practice 2', 'Man City Academy (Darren Bowman)', 'Apply side and central diamond patterns in directional possession.', '60 x 40 yard area with an end zone at each end; 7v7 plus a joker for the team in possession.', 'Blue starts dribbling in; score by receiving in the opposite end zone (defenders cannot enter). Then the other team restarts and attacks the other way with the joker as CB or DM.', 'Extra point for a penetrative pass between defenders.', 'Fully fluid positions; teams work end to end continuously.', 'Midfielders initiate play and wingers play between the lines; create +1 (e.g. DM drops between CBs).', '7v7 (+1)', 15, 15, '60 x 40 yards', 54.9, 36.6, NULL, false, false, true, NULL, 100),
  ('10v8 side diamond pattern functional practice', 'phase_of_play', 'overload', 'in_possession', 65, 65, 'Session 3: Practice 3', 'Man City Academy (Darren Bowman)', 'Rehearse side diamond patterns of a 4-3-3 against a defending 4-3-1.', 'Large area to one goal; 10 blues plus GK in 4-3-3 against 8 reds in 4-3-1.', 'Coach feeds the GK; blues use side diamonds to overload the wide area, e.g. LW receives between lines, sets for LCM, who plays the forward in behind to finish.', NULL, 'Used opposed later in the season; earlier can be unopposed.', 'Recognise which pattern to use and when; technical detail.', '10v8 (+GK)', 19, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('7v7+1 three-zone SSG, create overloads', 'small_sided_game', 'overload', 'in_possession', 66, 66, 'Session 3: Practice 4', 'Man City Academy (Darren Bowman)', 'Create +1 overloads around the ball to break lines.', 'Three zones with goals and GKs; blues 2-3-3 v reds 2-3-2 plus a yellow joker; 2v1+GK at the back.', 'Blues build out from the GK; if the DM drops it makes a 4v3 in the middle; one CB may step into midfield; wingers drop into pockets or enter the end zone for a 3v2 finish. Then reds restart from their GK with the joker.', 'Coach sets where players may move.', NULL, 'Central players get on the ball and turn; wingers play between lines.', '7v7 (+1) +GKs', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Side diamond pass and move circuit thirds', 'passing_unopposed', 'unopposed', 'in_possession', 68, 68, 'Session 4: Practice 1a', 'Man City Academy (Darren Bowman)', 'Play through the thirds from CB to winger to midfield and switch via the DM.', 'Half pitch with poles; CBs with balls, wingers wide, CMs behind poles, forward high, DM central.', 'CB steps in and plays RW in the half space, RCM steps up for the set, then plays the forward, who sets to the DM, who receives half-turned and switches to the other CB; mirror on the other side.', NULL, NULL, 'Correct foot for each pass and receive so play goes at full speed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 130),
  ('Side diamond box to box pass and move', 'passing_unopposed', 'unopposed', 'in_possession', 69, 69, 'Session 4: Practice 1b', 'Man City Academy (Darren Bowman)', 'Box to box combination using CB, winger, CM and forward.', 'Two balls in opposite corners; CBs, wingers in half spaces, CMs, forwards, mannequins.', 'CB touches forward and passes to the winger moving inside, who sets for the CM beyond the pole; CM plays the forward, who sets back; CM passes to the opposite start.', 'One-touch wingers; high ball speed.', 'Players rotate to next position.', 'CBs step in with first touch; CMs take first touch forward.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 140),
  ('7v7 two-zone SSG create 5v4 attack', 'small_sided_game', 'overload', 'in_possession', 71, 71, 'Session 4: Practice 3', 'Man City Academy (Darren Bowman)', 'Controlled build-up and timing central midfielders breaking forward to overload.', 'Half pitch in 2 halves, goals with GKs; 4 (+GK) v 3 in the low half, 3v4 in the high half.', 'Blues keep possession until the right moment to play forward to the forward (via DM); then LCM and RCM break forward for a 5v4 to finish. Reds winning it low can add 2 players for a 5v5; won high it is a normal 7v7.', NULL, NULL, 'Reactions and decisions under high tempo; rest with the ball.', '7v7 (+GKs)', 16, 16, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Break past opponent triangle drill, finish', 'finishing', 'unopposed', 'in_possession', 74, 74, 'Session 5: Practice 1a', 'Man City Academy (Darren Bowman)', 'First touch past an opponent and final pass for a finish.', 'Triangle of poles near the box; pole and cone gate; GK in goal.', 'A passes to B, who breaks through the gate and plays a diagonal for C''s run; C scores with one or two touches.', 'Firm ground passes at match speed.', 'Rotate A to B to C to A; change sides.', 'Shoulders forward on first touch; finish across goal, first time if possible.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Open up and switch triangle drill, finish', 'finishing', 'unopposed', 'in_possession', 75, 75, 'Session 5: Practice 1b', 'Man City Academy (Darren Bowman)', 'Opening up and switching with a diagonal for a third man finish.', 'Triangle with mannequins: DM, forward, CM, winger and GK.', 'DM passes to F, who plays across to CM; CM opens up past the mannequin and plays a diagonal for the winger''s third man run, who touches forward and shoots across goal.', 'Finish max 2 touches.', 'Both sides.', 'Shoulders forward on first touch.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 170),
  ('One-two, set and final pass triangle finish', 'finishing', 'unopposed', 'in_possession', 76, 76, 'Session 5: Practice 1c', 'Man City Academy (Darren Bowman)', 'Combination of one-two, set and diagonal final pass to finish.', 'As 1b: DM, CM, F, W, mannequins and GK.', 'DM one-two with CM, then to F; F sets for CM running round the mannequin; CM plays a diagonal for the winger''s third man run to shoot.', 'Finish max 2 touches.', 'Both sides.', 'Finish across goal.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 180),
  ('One-two, set, give and go triangle finish', 'finishing', 'unopposed', 'in_possession', 77, 77, 'Session 5: Practice 1d', 'Man City Academy (Darren Bowman)', 'Add a give and go between winger and forward before the finish.', 'As 1c.', 'DM one-two with CM, then to F; F sets for CM round the mannequin; CM passes to W; W sets for F, who plays W around the mannequin to shoot.', 'Finish max 2 touches.', 'Both sides.', 'Finish across goal, first time if possible.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Side diamond: receive between lines, finish', 'combination', 'unopposed', 'in_possession', 78, 78, 'Session 5: Practice 2', 'Man City Academy (Darren Bowman)', 'Side diamond combination with winger receiving in the half space and through pass to finish.', 'Pitch with mannequins, half space markers; GK, CBs, LB, LW, LCM, F.', 'GK to CB, across to other CB who steps up, CB into LW dropping inside in the half space, LW sets for LCM who touches to open up, then LW runs between mannequins and F double-moves to receive the through pass and score.', NULL, 'Coach sets other patterns.', 'Winger arrives in the middle of the half space: too high is cut out, too low can''t set to the CM.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Corners end zones switching possession', 'positional_game', 'overload', 'in_possession', 79, 79, 'Session 5: Practice 3', 'Man City Academy (Darren Bowman)', 'Switch play from corner to corner and keep shape in and out of possession.', '60 x 40 yard area with 4 corner zones 10 yards wide; 2 players per team in the zones; 4(+2) v 4(+2); coaches on the sides feed.', 'Blues score a point for switching from one corner zone to the other and for 6 passes; reds win the ball before 6 passes for a point and blues transition quickly.', 'Corner players one touch; 2-touch inside.', 'End zone players rotate with inside players after receiving.', 'Keep shape; combinations zone to zone; be ready to attack and defend.', '6v6 (4+2 v 4+2)', 12, 12, '60 x 40 yards', 54.9, 36.6, NULL, false, false, true, NULL, 210),
  ('5v5+1 four-goal conditioned SSG', 'small_sided_game', 'overload', 'in_possession', 80, 80, 'Session 5: Practice 4', 'Man City Academy (Darren Bowman)', 'Possession then quick attack and transitions to 4 small goals.', '60 x 40 yard area, 4 small goals (2 at each end), 5v5 plus joker.', 'Team must complete 6 passes before scoring in any of the 4 goals; same applies for the other team after winning it.', '6 passes before scoring.', 'V1 score anytime; V2 one-touch finish only; V3 one team keeps 10 passes for a point, other team wins it and scores (2 touch, 1 touch finish); V4 large goals with GKs.', 'Communication, quick decisions and transitions, control tempo.', '5v5 (+1)', 11, 11, '60 x 40 yards', 54.9, 36.6, NULL, true, false, true, NULL, 220),
  ('Combination play and finishing circuit', 'combination', 'unopposed', 'in_possession', 82, 82, 'Session 6: Practice 1', 'Man City Academy (Darren Bowman)', 'Practise combinations and finishing with correct weight, angles and first touch.', '2 large goals with GKs, cones/poles; groups on left and right.', 'Left: A one-two with B, B long ground pass to C, C one-two with D moving forward, D touches towards goal and finishes on the second touch.', 'Coach may add forfeits or time limits.', 'Players can become defenders applying pressure from behind or in front.', 'Weight of pass; half-turn; take on back foot; break line with first touch; right finish.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Midfield combos + crossing 6v4 functional', 'phase_of_play', 'overload', 'in_possession', 83, 83, 'Session 6: Practice 2', 'Man City Academy (Darren Bowman)', 'Midfield combinations to release a winger to cross for runners.', 'Half pitch to a goal with GK; blues DM, LCM, RCM, F, LW, RW against 4 red defenders; 3 small counter goals on the halfway line.', 'Coach passes to the DM; blues use City midfield combinations, F sets back for a CM to play wide; winger dribbles or gets in behind and crosses for oncoming runners. Reds who win it score in any of the 3 small goals.', NULL, NULL, 'Coach manages the defending unit''s positions, angles and aggression for realism; play between and behind.', '6v4 (+GK)', 11, 11, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('3v2 (+GK) attacking overload duels', 'one_v_one', 'overload', 'in_possession', 84, 84, 'Session 6: Practice 3a', 'Man City Academy (Darren Bowman)', 'Exploit a 3v2 to score with good runs and timing.', 'Area outside the box to goal with GK; reds in pairs, blues in groups of 3 waiting.', 'A red defender or GK serves to a blue attacker; 2 defenders step out and the 3 blues attack to score while the reds defend.', NULL, 'Time limit to score; rewards for defenders; other competitive conditions.', 'Diagonal runs and overlaps; time runs in behind; first touch changes angle; when to penetrate or keep it.', '3v2 (+GK)', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 250),
  ('4v3 (+GK) attacking overload duels', 'one_v_one', 'overload', 'in_possession', 85, 85, 'Session 6: Practice 3b', 'Man City Academy (Darren Bowman)', 'Create and exploit 1v1s within a 4v3 attack.', 'Half pitch to goal with GK; reds in groups of 3, blues in groups of 4 (DM, 2 wingers, forward).', 'Option 1: GK feeds the blues at halfway for a 4v3 attack. Option 2: GK feeds a red defender who attacks 3v3 aiming to pass to the blue DM target man on halfway.', NULL, 'Option 2 reverses roles.', 'Fast combinations, use the extra player, decide when to penetrate or keep it, right finish.', '4v3 (+GK)', 8, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Dynamic 2-zone 5v5 SSG overloads', 'small_sided_game', 'overload', 'in_possession', 86, 86, 'Session 6: Practice 4', 'Man City Academy (Darren Bowman)', 'Patient build-up then wingers join to create a 3v2 attack.', 'Area split by the halfway line into 2 zones, goals with GKs; 2v1 in the low zone, wide players waiting outside.', 'GK starts, blues keep possession and pick the moment to play into F; F sets back for one of 2 wide players who join to make a 3v2; the opposite winger keeps width and runs in behind. Then reds restart from their GK, roles reversed.', NULL, 'Adjust area size for age/level.', 'Occupy the right spaces at the right times.', '5v5 (+GKs)', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Triangle drill with set through combination', 'passing_unopposed', 'unopposed', 'in_possession', 88, 88, 'Session 7: Practice 1', 'Man City Academy (Darren Bowman)', 'One-touch combination with a set and through pass for a third man run.', 'Mannequins/poles 15-30 yards apart, pole and cone gates, wide poles as defenders.', 'A passes to B who breaks through the gate, B one-two with A, B passes to C, A sets and C makes a third man run to receive the through pass, then C passes to A2 at the start.', 'One touch, high ball speed.', 'Rotate A to B to C to A; change direction.', 'Eye contact and timing; weight of pass to break the line.', NULL, NULL, NULL, '15-30 yards between poles', NULL, NULL, NULL, false, false, true, NULL, 280),
  ('Central diamond, crossing vs 2 box defenders', 'finishing', 'passive', 'in_possession', 89, 89, 'Session 7: Practice 2', 'Man City Academy (Darren Bowman)', 'Central diamond combination leading to wide play, crossing and finishing.', 'Half pitch with GK; DM, LCM, RCM, F, LW, RW, LB, RB; 2 red defenders inside the box; yellow wide zone and small red cut-back zone.', 'DM touches forward and passes to a CM, who finds F within the semi-circle width; F sets for the other CM, who plays to the winger''s feet or in behind; winger crosses. Front post for F, back post for the far winger, cut-back to the CM from the red zone.', 'Where the winger receives decides the cross type.', 'Defenders progress from passive to fully active; variation with the full back overlapping.', NULL, '8v2 (+GK)', 11, 11, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('5v2 (+GKs) SSG for 3v2 finish', 'phase_of_play', 'overload', 'in_possession', 90, 90, 'Session 7: Practice 3', 'Man City Academy (Darren Bowman)', 'Build from the GK through full back and forward into a 3v2 finish.', '30 x 15 yard area, goals with GKs; 2 teams of 5, playing 5v2.', 'GK to LB or RB, who plays into F, who sets for a central midfielder; blues then attack 3v2 to finish. Full backs stay back.', 'Rotate defenders for rest; swap team roles after a set time.', 'Add a red defender and let one full back join for a 4v3.', 'Create overloads with combinations; attack space behind defenders.', '5v2 (+GKs)', 10, 12, '30 x 15 yards', 27.4, 13.7, NULL, true, true, true, NULL, 300),
  ('7v7 two-zone SSG, full backs join', 'small_sided_game', 'overload', 'in_possession', 91, 91, 'Session 7: Practice 4', 'Man City Academy (Darren Bowman)', 'Full backs push on to create a 5v4 attack while defending a counter.', 'Box to box area split by the halfway line, goals with GKs; 4v3 in the low zone at the start.', 'GK starts, blues keep possession and play into their front 3; then LB and RB move up for a 5v4 in the high zone, leaving 2v3 behind. Reds who win it counter quickly 3v2; if reds win it in the first phase their 2 full backs join for a 5v4.', NULL, 'Remove the halfway line for a normal SSG with the same principles.', 'High tempo; recognise when to rest on the ball; quick correct decisions.', '7v7 (+GKs)', 16, 16, 'Box to box', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Triangle drill with overlapping runs', 'passing_unopposed', 'unopposed', 'in_possession', 93, 93, 'Session 8: Practice 1a', 'Man City Academy (Darren Bowman)', 'One-touch combination finishing with an overlapping run to receive.', 'Mannequins/poles 15-30 yards apart, pole and cone gates, A, B, C, D positions.', 'A to B through the gate, B one-two with A, B to C who breaks forward through the gate, C passes for D''s overlapping run and D dribbles back to the start.', 'One touch, high ball speed.', 'Rotate A to B to C to D to A; change direction.', 'Eye contact and timing; weight of pass.', NULL, NULL, NULL, '15-30 yards between poles', NULL, NULL, NULL, false, false, true, NULL, 320),
  ('Triangle drill with quick one-two combinations', 'passing_unopposed', 'unopposed', 'in_possession', 94, 94, 'Session 8: Practice 1b', 'Man City Academy (Darren Bowman)', 'One-touch combinations with quick one-twos.', 'Same set-up as 1a.', 'A to B through the gate, B one-two with A, B to C who breaks forward then plays back to B, B passes for D''s run and D dribbles to the start.', 'One touch, high ball speed.', 'Rotate A to B to C to D to A; change direction.', 'Eye contact and timing; weight of pass.', NULL, NULL, NULL, '15-30 yards between poles', NULL, NULL, NULL, false, false, true, NULL, 330),
  ('Central diamond with wing play and crossing', 'combination', 'unopposed', 'in_possession', 95, 95, 'Session 8: Practice 2', 'Man City Academy (Darren Bowman)', 'Attacking midfielders in half spaces combine with the forward to release the winger to cross.', 'Half pitch to goal with GK and mannequins; DM, LCM, RCM, F, LW, RW; yellow wide and red cut-back zones.', 'DM one-two with a CM; DM passes to F, who has been moving between CB and DM mannequins; F sets back to the CM on that side, who touches and plays the winger''s feet or in behind. Winger crosses to front or back post, or cuts back for the CMs.', 'Where the winger receives decides the cross type.', NULL, 'Set with the correct foot; forward spins to time his run into the box.', NULL, NULL, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('3v2 to 4v3 attacking overload duels', 'one_v_one', 'overload', 'in_possession', 96, 96, 'Session 8: Practice 3', 'Man City Academy (Darren Bowman)', 'Two-phase overload attacks, 3v2 then 4v3.', 'Half pitch to goal with GK; blues waiting at halfway, reds beside the goal.', 'Phase 1: a red or GK feeds a blue and 3 blues attack 2 reds. Phase 2: a new ball, 4 new blues attack 3 reds (the 2 reds stay).', 'Consider time limits to score and rewards for defenders.', NULL, 'Competitive, high intensity; first touch that changes angle; when to penetrate or keep it.', '3v2 then 4v3 (+GK)', NULL, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 350),
  ('8v8 (+GKs) game principles and patterns', 'small_sided_game', 'opposed', 'in_possession', 97, 97, 'Session 8: Practice 4', 'Man City Academy (Darren Bowman)', 'Use learned patterns of play to create overloads in an even game.', 'Large area with goals and GKs; blues 4-3-1 v reds 3-3-2.', 'Blues look for patterns, e.g. side diamond: when the forward pass is blocked, CB to LB to F, F sets for LCM, who plays a through pass for RCM''s deep run.', NULL, 'Used opposed later in the season.', 'Occupy the right spaces, break lines, attack space behind.', '8v8 (+GKs)', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Final third switch and combination, crossing', 'combination', 'unopposed', 'in_possession', 99, 99, 'Session 9: Practice 1a', 'Man City Academy (Darren Bowman)', 'Switch play and combine in the final third to cross and finish.', 'Final third with GK and mannequins; LB, LCM, F, RCM, RW, LW; yellow wide and red cut-back zones.', 'LB passes to LCM, LCM to F, F sets for RCM, RCM touches and plays RW wide, RW dribbles into the yellow zone and crosses: F front post, LW back post. Or RCM plays through into the red zone and RW cuts back to a CM.', NULL, 'Repeat from the right side; full back overlap variation (Practice 1b).', 'Whether the CM plays to feet or behind depends on the winger''s movement.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Final third: winger inside, full back overlaps', 'combination', 'unopposed', 'in_possession', 100, 100, 'Session 9: Practice 1b', 'Man City Academy (Darren Bowman)', 'Winger moves inside to create space for the overlapping full back to cross.', 'As 1a plus RB.', 'LB to LCM, LCM to F, F sets for RW who has come inside to the half space; RW sets for RCM, who passes in behind for RB''s overlap into the wide zone; RB crosses to the back post for LW, or cuts back to a CM or across for F.', NULL, 'Repeat from the other side.', 'Midfielders start play, full backs push on, wingers between lines.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Break the line 4v4 end zone game', 'positional_game', 'opposed', 'in_possession', 101, 101, 'Session 9: Practice 2', 'Manchester City Academy', 'Penetrating passes that break the defensive line and play through or around opponents to an end zone.', 'Rectangle (30x20 up to 60x40 yards) with an end zone at each end; two teams of 4 (can be overloaded e.g. 5v4); balls at the sides.', 'A blue dribbles in from an end zone; blues try to combine and pass into a team-mate receiving in the far end zone, then turn and attack the opposite end zone. Reds press to win it and then swap roles and attack.', 'Score by receiving in the end zone; a pass that bypasses defenders earns an extra point.', 'Play the full area with defenders allowed into the end zones to apply pressure.', 'Open up in a diamond shape; quick combinations; support behind and ahead of the ball; play between and behind; be ready to attack and defend; move to the ball; use first touch to break the line and create overloads.', '4v4', 8, 10, '30 x 20 to 60 x 40 yards', 27.4, 18.3, NULL, false, false, true, NULL, 390),
  ('Wide overload 3v2 in channels', 'phase_of_play', 'overload', 'in_possession', 102, 102, 'Session 9: Practice 3', 'Manchester City Academy', 'Wide players making inside diagonal runs and central midfielders running beyond to create and finish a 3v2 overload in two channels.', 'Half a pitch split into 3 vertical channels with a goal and GK; full backs, wingers, central midfielders and a forward against 2 red defenders; players outside the active channels are unused.', 'Starting from a full back (e.g. RB), the attackers play within two channels: RB one-two with RW, pass into F, RW cuts inside to take F''s lay-off and slips a through ball for LCM''s run to finish. As soon as it ends the opposite full back starts a new attack using the other two channels.', 'Attack only within 2 channels; finishes go across the GK so F can follow in on rebounds.', 'Alternate the starting full back side.', 'Wide players make inside diagonal runs; attack space behind defenders; follow in on rebounds.', '4 attackers v 2 defenders + GK (per phase)', 10, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Two-zone 5v5 overload game (repeat)', 'small_sided_game', 'overload', 'in_possession', 103, 103, 'Session 9: Practice 4 (book repeats its p.86 practice)', 'Manchester City Academy', 'Choosing the right moment to play forward and creating overloads through combinations.', 'Area split by halfway into 2 zones, goal and GK at each end; 5v5 plus GKs; 2v1 in the low zone and 3v2 in the high zone.', 'The GK starts; blues keep the ball in the 2v1 low zone and then play into the forward, who sets back for a wide player joining from outside to make a 3v2. The opposite winger holds width and runs in behind to score. After the attack the reds'' GK restarts the other way with roles reversed.', NULL, NULL, 'Occupy the right spaces at the right times; create overloads through combinations.', '5v5 + 2 GKs', 12, 12, 'Adjust to age/level', NULL, NULL, NULL, true, true, true, NULL, 410),
  ('Final third support combination and cross', 'combination', 'unopposed', 'in_possession', 105, 105, 'Session 10: Practice 1', 'Manchester City Academy', 'Supporting play and a final-third combination that ends in a cross and finish.', 'Final third with goal and GK, red mannequins as the back four, wide yellow zones and a small central red zone; blue CMs, forward, wingers and full backs.', 'RCM passes into F, who lays off for the oncoming LCM; LCM touches forward and finds LW near the line, who dribbles into the wide zone and crosses; F attacks the front post and the far winger the back post. Alternative: LCM slides LW through into the small red zone and LW cuts back to a central midfielder at the box edge.', NULL, 'Repeat from the other side; start from the full backs; winger moves inside with the full back overlapping.', 'Whether the CM passes to the winger''s feet or in behind depends on the winger''s movement and decision.', 'Unit of 6-7 + GK', 7, 9, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Deep runs in behind plus crossing', 'finishing', 'passive', 'in_possession', 106, 106, 'Session 10: Practice 2', 'Manchester City Academy', 'Timed midfield runs in behind the back line and finishing from through balls or crosses.', 'Final third with goal, GK and back-four mannequins; 2 blue CMs, 2 wingers, a DM or coach with balls in the centre circle; 2 red defenders beside the goal that the coach can add.', 'The coach/DM passes to a CM. Option 1: CM receives on the half-turn and plays in behind for the other CM, who runs straight between the full back and centre back mannequins to take the diagonal pass and finish. Option 2: CM passes wide and the winger crosses while the other three attack the box.', 'Two touches maximum for the CMs (control + pass; receive + finish).', 'Coach brings in the 2 red defenders; work both sides.', 'Receive on the back foot; time the run between mannequins.', '4 attackers + DM/coach + GK (+2 defenders)', 6, 8, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Side diamond patterns 10v8 (repeat)', 'phase_of_play', 'overload', 'in_possession', 107, 107, 'Session 10: Practice 3 (book repeats its p.65 practice)', 'Manchester City Academy', 'Using side diamond patterns in a 4-3-3 to overload wide areas against a 4-3-1.', 'Two thirds of the pitch, one goal with GK; blues 10 in 4-3-3 vs 8 reds in a 4-3-1; coach serves from the back.', 'The coach plays in and the blues use side diamond movements (e.g. full back, winger, CM rotations) to receive between the lines, set for a central midfielder and play through for the forward to finish.', NULL, 'Used opposed in the later part of the season.', 'Recognise which pattern to use at the right time; coach watches technical and tactical detail.', '10v8 + GK', 19, 19, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Back to back goals 5v5 overloads (repeat)', 'small_sided_game', 'opposed', 'in_possession', 108, 108, 'Session 10: Practice 4 (book repeats its p.56 practice)', 'Manchester City Academy', 'Creating 3v2 overloads by quick combinations and good timing.', '60 x 40 yards, two large goals with GKs placed back to back in the middle; two teams of 5.', 'The coach starts; the team in possession builds and tries to make a 3v2 near the opposite goal and score; exploit transitions.', NULL, 'Younger/lower levels: 2v2 in each half plus 2 floating jokers; or 3v3 in one half and 2v2 in the other.', 'Occupy the right spaces at the right times; keep the ball, then go when the 3v2 is on.', '5v5 + 2 GKs', 12, 14, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 450),
  ('Side diamond when CB is blocked', 'combination', 'unopposed', 'in_possession', 110, 111, 'Session 11: Practice 1a/1b', 'Manchester City Academy', 'A side diamond combination (CB, FB, CM, winger) used when the centre back''s forward pass is shut off.', 'Two thirds of the pitch with goal and GK; red mannequins as the opposition back four and midfield; channels and half-spaces marked; a red presser blocks the CB''s forward pass.', 'With the pass forward blocked the CB plays the level LB; the winger holds high and wide so LB passes into F, who sets for the oncoming LCM. LCM takes a touch to open up and plays a diagonal ball for RCM running between the CB mannequins to finish.', NULL, '1b: mirrored on the right, starting with a short GK pass; RCM plays into the half-space for LCM''s run between CB and FB mannequins, who finishes across the GK.', 'Occupy the right spaces at the right times and break lines; FB level with the ball carrier; take a touch to open up rather than playing first time.', 'Full team shape, unopposed', 9, 12, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('4v4+3 defensive organisation possession', 'defending', 'overload', 'out_of_possession', 112, 112, 'Session 11: Practice 2', 'Manchester City Academy', 'Defending as a compact diamond of 4 to stop a 7-player team playing through the middle.', '10 x 15 yards; two teams of 4 plus 3 yellow jokers who play with the team in possession.', 'The coach serves to the reds, who keep the ball with the 3 jokers. The blues press together to close angles and win it; when they do, the teams switch roles.', 'Jokers always play for the team in possession.', 'Position specific: blues as forward, 2 CMs and a DM.', 'Stop play through the centre; force it wide to create 1v1/2v2; keep the ball in front and protect space behind; press as a unit; know when to press and when to drop.', '4v4+3', 11, 11, '10 x 15 yards', 13.7, 9.1, NULL, false, false, false, NULL, 470),
  ('Set the trap 6v8 pressing phase', 'defending', 'opposed', 'out_of_possession', 113, 113, 'Session 11: Practice 3', 'Manchester City Academy', 'A coordinated front press that forces play wide to trap the opponent.', 'Half to two thirds of the pitch, red GK and team (8) building up; 6 blues pressing (forward, wingers, CMs, DM).', 'Red GK plays to a CB; blue RCM steps onto the red DM to free F, who splits the CBs and shows play wide. The near winger presses the full back, the near CM marks tight, the DM balances to cover F and the far winger blocks the switch.', NULL, NULL, 'Get compact, stop the switch, squeeze the ball, keep it in front, protect depth and drop if there is no pressure.', '6v8 + GK', 15, 15, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('5v5+1 four-goal midfield defending', 'small_sided_game', 'overload', 'out_of_possession', 114, 114, 'Session 11: Practice 4', 'Manchester City Academy', 'Defending in midfield while outnumbered, using pressing triggers and a chain reaction to win the ball.', '40 x 30 yards, 2 small goals at each end; 5v5 plus a yellow joker for the reds (5v6).', 'The coach serves to the reds, who try to score in either of 2 small goals. The blues defend in a 2-1-2 shape; once the first presser goes the rest react together. If the blues win it they score quickly in the other 2 goals.', 'Reds have no conditions.', NULL, 'Know your role; force the ball where we want it, win it and counter to score; protect depth, keep ball in front.', '5v5+1', 11, 11, '40 x 30 yards', 36.6, 27.4, NULL, true, false, true, NULL, 490),
  ('Side diamond, set and overlap cross', 'combination', 'unopposed', 'in_possession', 116, 116, 'Session 12: Practice 1', 'Manchester City Academy', 'Winger receives in the half-space between lines, sets back and the full back overlaps to cross.', 'Two thirds of the pitch with goal and GK; red mannequins in two lines; half-spaces marked; full blue team shape.', 'GK to CB, across to the other CB who steps forward and plays into RW dropping inside into the half-space. RW sets for RCM, who touches to open up and passes between the FB and CB mannequins for the overlapping RB to cross; F and LW attack the box.', NULL, NULL, 'Winger must receive in the middle of the half-space; open up with a touch rather than first time.', 'Full team, unopposed', 9, 12, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Two-zone 5v5 transition with 5v2 press', 'transition', 'overload', 'to_defend', 117, 117, 'Session 12: Practice 2', 'Manchester City Academy', 'Pressing outnumbered and quick transitions between two zones.', '30 x 20 yards split into 2 equal zones; two teams of 5.', 'The coach serves; the reds keep the ball in one zone while 2 or 3 blues press. If the blues win it they pass to team-mates in the other zone, and 2-3 reds must sprint across to press; roles swap.', '10 passes = 1 point for the team in possession.', 'Vary between 2 and 3 pressers (5v2 or 5v3).', 'Keep the ball moving; keep shape out of possession; press together; make even numbers near the ball; move it quickly to a free player; react fast on losing it.', '5v5', 10, 10, '30 x 20 yards', 27.4, 18.3, NULL, false, false, false, NULL, 510),
  ('Set the trap 10v10 man-for-man press', 'conditioned_game', 'opposed', 'out_of_possession', 118, 118, 'Session 12: Practice 3', 'Manchester City Academy', 'A full man-to-man press from the front that makes equal numbers around the ball and leads to a counter.', 'About two thirds of the pitch, one goal with GK; 10 reds plus GK build up against 10 blues; a red line to play/dribble past.', 'Red GK plays out; blue RCM steps onto the red DM, freeing F to press; LCM sprints to the receiving CB, DM marks red RCM, CB pushes onto red F, LW presses RB and LB steps to RW for 4v4 near the ball while the far side shifts to cover the switch.', 'Reds score by playing or dribbling past the line; blues win it and counter to score.', NULL, 'Chain reaction from the first presser; create equal numbers around the ball; balance at the back.', '10v10 + GK', 21, 21, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 520),
  ('Three-team 6v6 pressing from the front', 'small_sided_game', 'opposed', 'out_of_possession', 119, 119, 'Session 12: Practice 4', 'Manchester City Academy', 'Pressing from the front in a compact shape to stop penetrating passes, with a numerical edge near the ball.', 'Area as shown (large) with 2 goals and GKs; two teams of 6 (2 CBs, DM, 2 CMs, F) plus a third team waiting outside.', 'The GK starts; the reds build up and try to play through to score; the blues identify triggers, press with a chain reaction and counter to score, leaving the far red CM unmarked.', 'Rotate teams after conceding a goal or a set time e.g. 5 minutes.', NULL, 'Show opponents outside starting from the front players; compact block with a high line.', '6v6 + GKs + 6 waiting', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 530),
  ('Winger sets for CM, forward opens up', 'combination', 'unopposed', 'in_possession', 121, 121, 'Session 13: Practice 1', 'Manchester City Academy', 'Breaking the midfield line via the winger and a forward who opens his body to receive and finish.', 'Two thirds of the pitch, goal and GK; red mannequins as midfield and centre backs; blue CBs, CMs, wingers and forward; coach in the centre circle.', 'GK passes short to a CB who steps up and finds RW coming off the line. RW sets back to RCM, who starts inside the mannequin and moves into the open channel; RCM touches forward and passes to F, who stays high and central, opens up past the mannequin, touches into the box and shoots across goal into the far corner.', NULL, 'Repeat on the left with LCM and LW, F opening up the other way.', 'Winger comes off the line at the right angle; RCM''s first touch forward opens both sides; forward opens his body shape.', '7 + GK, unopposed', 8, 10, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 540),
  ('Two-zone 6v6 transition with 6v4 press', 'transition', 'overload', 'to_defend', 122, 122, 'Session 13: Practice 2', 'Manchester City Academy', 'Pressing outnumbered in midfield and fast transitions to the other zone.', '35 x 25 yards split into 2 equal zones; two teams of 6.', 'The coach serves to the reds, who keep the ball in one zone while 4 blues press. If the blues win it they pass to team-mates in the other zone and 4 reds sprint across to press; roles swap with the same aims.', '10 passes = 1 point for the team in possession.', NULL, 'Keep the ball moving with good decisions; keep shape; press collectively; make even numbers around the ball (1v1 to 4v4); move it fast to a free player; react quickly to regain.', '6v6', 12, 12, '35 x 25 yards', 32.0, 22.9, NULL, false, false, false, NULL, 550),
  ('Continuous overloads 2v1 to 6v5', 'defending', 'overload', 'out_of_possession', 123, 123, 'Session 13: Practice 3', 'Manchester City Academy', 'Defending outnumbered against growing overloads, closing down and making even numbers near the ball.', '40 x 25 yards with one large goal and GK; two teams of 6; reds queue at the far end, blues beside the goal; coach with balls at the side.', 'The GK serves to red 1, and reds 1 and 2 attack blue 1 (2v1). When it ends the coach serves the next red, who joins with one more red against an added blue for 3v2; it continues through 4v3, 5v4 and 6v5.', 'Reds attack every time with a ball from the GK or coach and try to score quickly.', NULL, 'Close down fast and create equal numbers near the ball; know when and how to win it; communicate when to press or drop; keep the ball in front and protect depth.', '6v6 + GK', 13, 13, '40 x 25 yards', 36.6, 22.9, NULL, true, true, true, NULL, 560),
  ('Stop 3v2s in back-to-back goals 6v6', 'small_sided_game', 'overload', 'out_of_possession', 124, 124, 'Session 13: Practice 4', 'Manchester City Academy', 'Defending in units of three to prevent 3v2 overloads and force play away from goal.', '60 x 40 yards, two large goals with GKs back to back in the centre; two teams of 6 plus a joker.', 'The coach serves; the team in possession uses the joker to create 3v2 overloads and score. Defenders work in threes, forcing play one way, taking balanced positions and protecting space behind.', 'Joker plays for the team in possession.', NULL, 'Always see ball and opponent; dictate play without the ball; force it where we want, win it and counter; show leadership and communication.', '6v6+1 + 2 GKs', 15, 15, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 570),
  ('Midfield and forward unit free combinations', 'combination', 'unopposed', 'in_possession', 126, 126, 'Session 14: Practice 1', 'Manchester City Academy', 'Midfield and forward units (3-3 of a 4-3-3) choosing their own pattern to finish with a cross.', 'Final third with goal and GK, wide yellow zones and small red zones by the box; DM, 2 CMs, F and 2 wingers; balls with the coach in the centre circle.', 'Example: DM plays into F, who sets for the oncoming RCM; RCM touches forward and plays wide or in behind to RW depending on his run; RW crosses for F, LCM or LW.', 'Where the winger receives decides the cross: in the wide zone, cross to front (F) or back post (far winger); in the small red zone, cut back to the CMs at the box edge.', 'Players free to use any of the team''s patterns.', 'Read the winger''s movement to choose feet or in behind.', '6 + GK', 7, 7, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Three-team 5v5v5 pressing transition game', 'transition', 'overload', 'out_of_possession', 127, 127, 'Session 14: Practice 2', 'Manchester City Academy', 'Possession under pressure and pressing to cut out passes through a middle zone.', '60 x 40 yards split into three 20-yard zones; reds and yellows in the end zones, blues in the middle; coaches with balls at each side.', 'The coach serves to the reds and 3 blues run in to press (5v3) while 2 stay in the middle to intercept. Reds complete 3 passes then play through to the yellows for a point; 3 blues then press the yellows. If the blues win it, they swap roles with the team that lost it.', '3 passes before transferring; can restrict to passes below head height through the middle.', NULL, NULL, '5v5v5', 15, 15, '60 x 40 yards', 54.8, 36.6, NULL, false, false, true, NULL, 590),
  ('Diamond midfield press 9v9 tactical game', 'conditioned_game', 'opposed', 'out_of_possession', 128, 128, 'Session 14: Practice 3', 'Manchester City Academy', 'Pressing from the front with a diamond midfield to secure the centre when the ball goes wide.', 'Large area with 2 large goals and GKs; 9v9.', 'Red GK plays to a defender and the reds build up to score. Blue F shows play one way; when the GK plays to the red RB, RCM steps onto the red DM to free the ACM to press while keeping 3v3 centrally; LCM marks tight, DM picks up the red ACM, LB pushes up and RB tucks across for a 3v1 at the back. Blues win it and counter.', NULL, NULL, 'High density of players on the ball side, leave the far side empty; the far red CM is left free because the pass is hard.', '9v9 + 2 GKs', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 600),
  ('Multi-zone end to end pressing 6v6', 'defending', 'opposed', 'out_of_possession', 129, 129, 'Session 14: Practice 4', 'Manchester City Academy', 'Pressing from the front and defending through the thirds as connected units.', 'Pitch divided into zones with a GK/coach target at each end; 6v6; CBs and forwards held in the end zones, 3v3 in the middle zone (DM channels are only a reference).', 'Start from the GK with a 2v1 in the first zone; reds try to play through to the far target man (GK). When a red CB gets it, blue F presses and blocks the pass back to make 1v1 and RCM jumps onto the red DM for 3v3 near the ball. After the target receives he plays to a blue CB and the roles reverse.', 'CBs and Fs stay in end zones, except the CB on the ball may step forward (and F may follow).', NULL, 'Build links between units; defend as a block; delay; deny space; protect depth.', '6v6 + 2 GKs', 14, 14, NULL, NULL, NULL, NULL, false, true, true, NULL, 610),
  ('Four-line passing drill through thirds', 'passing_unopposed', 'unopposed', 'in_possession', 131, 131, 'Session 15: Practice 1', 'Manchester City Academy', 'Angles of support, receiving foot and timing movement off the poles to move the ball through thirds.', 'Area split into marked thirds with poles; groups of 6: one player per pole plus an extra at each end (A, B, C, D, D2, A2).', 'Variation 1: A passes to C who moves wide; C sets for B, who double-moves to receive on the other side; B plays forward to D who comes off his pole at an angle; D dribbles round back to the start. Players rotate A to B to C to D2 to D to A2, and A2 starts again.', NULL, 'Variation 2: A plays to B, B sets back, A then passes to C and the rest as before.', 'Pass and set with the correct (back) foot; central players start on the poles and time movement away.', 'Groups of 6', 6, 6, NULL, NULL, NULL, NULL, false, false, true, NULL, 620),
  ('Diamond midfield press 8v9 functional', 'defending', 'opposed', 'out_of_possession', 133, 133, 'Session 15: Practice 3', 'Manchester City Academy', 'Timing the press with a diamond midfield, protecting depth and stopping passes through.', 'Two thirds of the pitch; red GK and team building up; 8 blues pressing; red line to dribble past.', 'Blues first let the reds build with a 3v1, then pick the moment to press. F shows play one way; on the pass to red RB, RCM marks the red DM to free the ACM to press, keeping 3v3 centrally; LCM marks tight, DM takes the red ACM, LB steps up and RB tucks across for a 2v1 at the back. Blues win it and counter.', 'Reds score by dribbling past the red line.', NULL, 'Timing of the press; protect depth; stop penetrating passes.', '8v9 + GK', 18, 18, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 630),
  ('Back four reaction to coach call', 'defending', 'unopposed', 'out_of_possession', 136, 137, 'Session 16: Practice 1', 'Manchester City Academy', 'Back four closing down and covering together, forming a defensive arc when the ball goes wide.', '6 coloured mannequins as possible opponents on the ball (LDM/RDM, LW, RW, LF/RF); a back four of 4 blues in set start positions; coach in the centre circle.', 'Part 1: the coach calls a colour (e.g. green = left forward); the nearest CB closes the new ball carrier and the other three tuck in to cover. Part 2: coach calls red (back to the DM) so the line resets, then blue (the right winger); the LB presses and the other three shift across in an arc.', NULL, 'Part 2 adds the reset and wide pass to the winger.', 'Keep 10-12 yard distances and the right line height for central or wide receivers; the unit moves as fast as the ball; body shape to defend 1v1; watch team-mates'' body positions.', 'Back 4 + coach', 4, 5, NULL, NULL, NULL, NULL, false, false, false, NULL, 640),
  ('8v4 overload possession in 3 phases', 'possession', 'overload', 'in_possession', 138, 138, 'Session 16: Practice 2', 'Manchester City Academy', 'Purposeful possession, creating space with a numerical advantage, and quick reactions in transition.', '60 x 40 yards; 8 blues v 4 reds.', 'Phase 1: 4v4 inside with 4 blues on the sides; outside players cannot pass to each other or come inside unless they pass in. Phase 2: inside and outside players swap after passing. Phase 3: 8v4 all inside.', '10 passes = 1 point; defenders score a point by winning it; outside players one touch.', 'Phases 1 to 3.', 'Quick support; create space in possession, deny it out of possession; know when to go round or through; control tempo; communicate; react fast to transition.', '8v4', 12, 12, '60 x 40 yards', 54.8, 36.6, NULL, false, false, false, NULL, 650),
  ('Back four defend the box 6v4', 'phase_of_play', 'overload', 'out_of_possession', 139, 139, 'Session 16: Practice 3', 'Manchester City Academy', 'A compact back four defending around the box against attacks down one side.', 'Half pitch, goal and GK, 4 channels marked; blue back four; reds (5, or 6 with the DM) including a DM on halfway.', 'GK plays long to the red DM, who passes left or right; reds attack through that side to score. If the winger dribbles and crosses, the defenders drop. Blues who win it score by passing to the red DM target.', 'Reds score from the same side the ball was played to.', NULL, 'Angles and distances relative to pitch width and ball; communicate; protect space behind with a defensive arc when wide; spot danger with correct body shape.', '6v4 + GK', 11, 11, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 660),
  ('Defend the box 8v6 phase of play', 'phase_of_play', 'overload', 'out_of_possession', 140, 140, 'Session 16: Practice 4', 'Manchester City Academy', 'Back four plus two DMs staying compact around the box, with an arc when the ball is wide.', 'Half pitch plus, goal and GK; blues are back 4 + 2 DMs; reds are midfield and forward units + 2 full backs; a red line to dribble over.', 'Reds build up, create overloads and try to score. Blues keep a compact shape with the ball in front; if they win it they dribble over the red line for a point.', 'Blues score 1 point by dribbling over the line.', NULL, 'Correct angles and distances to the ball; protect depth; know when to press or drop; tight when central; arc when the ball is wide.', '8v6 + GK', 15, 15, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 670),
  ('Defend long passes then crosses', 'defending', 'opposed', 'out_of_possession', 142, 142, 'Session 17: Practice 1', 'Manchester City Academy', 'Back four defending a long pass and then readjusting to defend a second-phase cross.', 'Half pitch with goal and GK; blue back four; red full backs and wingers with balls in wide queues; F nearby.', 'Phase 1: a red full back dribbles and hits a long pass; the defenders clear high and wide or out of play. Phase 2: a red winger dribbles and crosses; the back four reset to defend it from either side.', NULL, 'Lower ages/levels: 60 x 40 yards.', 'Angles and distances; be aggressive, decisive and smart; drop if no pressure on the ball; choose header or volley and clear high and wide; reset quickly for the second phase.', 'Back 4 + GK v wide attackers', 9, 13, 'Half pitch (60 x 40 yards for younger)', NULL, NULL, NULL, true, true, true, NULL, 680),
  ('Defend the box 8v8 phase of play', 'phase_of_play', 'opposed', 'out_of_possession', 143, 143, 'Session 17: Practice 2', 'Manchester City Academy', 'A compact block defending around the box against attacks down one side.', 'Half pitch split into 4 reference channels, goal and GK; 8v8 with the red DM on halfway.', 'The red DM plays to either side and the reds attack through that side to score. Blues stay compact; if they win it they score by passing to the red DM target.', NULL, NULL, 'Correct angles and distances; protect space behind with an arc when wide; communicate drop or press; compact when the ball is central.', '8v8 + GK', 17, 17, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 690),
  ('Defending crosses functional practice', 'defending', 'opposed', 'out_of_possession', 144, 144, 'Session 17: Practice 3', 'Manchester City Academy', 'Centre backs and GK defending varied crosses and starting the attack after a clearance.', 'Final third with goal and GK; red mannequins as full backs; red wingers and CMs; 2 blue CBs; coach/DM with balls in the centre circle.', 'Coach/DM plays wide to a winger; the 2 CBs enter and position for the ball. The winger attacks the mannequin and whips in, lofts or cuts back; defenders clear with head or volley back the way it came, or control and pass to the coach. GK chooses to catch or punch and can throw/kick to the coach.', NULL, 'Practise many kinds of cross into the defensive third.', 'Stay in line with the ball to read the cross; clear high back towards where it came from; GK starting position and communication.', '2 CBs + GK v wide and central attackers', 7, 9, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 700),
  ('Zonal 2v3 defending as a pair', 'phase_of_play', 'overload', 'out_of_possession', 145, 145, 'Session 17: Practice 4', 'Manchester City Academy', 'Two defenders working as a pair against a 3v2 to stop central passes into the forward.', 'Half pitch with goal and GK, divided into halves; blue CB and RB defend one side; red DM on halfway as target and server; reds F, winger and CM.', 'GK plays long to the red DM, who passes to either side for a 3v2 attack with F moving across. If the 2 blues win it, they pass to the red DM (target) for a point.', 'Blues score 1 point by passing successfully to the red DM.', 'Switching play: the DM can switch to the other side, half restrictions are removed and the back four defend together (6v4).', 'Stop passes into F, aware of angles and distances; keep ball in front and protect depth; force it wide for 1v1 and 2v2; press as a unit; deepest defender organises.', '3v2 + GK (progresses to 6v4)', 6, 11, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 710)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
